mapper.insert:
INSERT INTO health_alerts (
    user_id, alert_type, alert_level, current_value, threshold_value, 
    vital_sign_id, is_read, read_time, create_time
) VALUES (
    #{userId}, #{alertType}, #{alertLevel}, #{currentValue}, #{thresholdValue}, 
    #{vitalSignId}, #{isRead}, #{readTime}, #{createTime}
)

mapper.select:
SELECT * FROM health_alerts
WHERE user_id = #{userId}
ORDER BY create_time DESC
LIMIT #{limit}
